//! The expected output in `fixtures/background` was written by hand from the
//! Claude Code schema, not generated by this adapter.

use std::collections::BTreeMap;
use std::sync::Arc;

use chrono::{DateTime, TimeZone, Utc};
use serde_json::{Value, json};
use vertebrae_harness_claude::{ClaudeDecodeContext, ClaudeStreamDecoder};
use vertebrae_harness_core::{
    EventId, HarnessEventDraftV1, HarnessEventPayloadV1, HarnessEventV1, ProviderThreadRef,
    SessionId, StreamId, ToolStatus, TurnId,
};

const FIXTURE: &str = include_str!("fixtures/background/claude-code-2.1.322.jsonl");
const EXPECTED: &str = include_str!("fixtures/background/claude-code-2.1.322.expected.json");

fn decoder(session: &str, stream: &str) -> ClaudeStreamDecoder {
    ClaudeStreamDecoder::with_root_locator_resolver(
        ClaudeDecodeContext::interactive(SessionId::from(session), StreamId::from(stream)),
        Some(Arc::new(|session_id: &SessionId| {
            Ok(Some(ProviderThreadRef::new(format!(
                "fixture://{}",
                session_id.as_str()
            ))))
        })),
    )
}

fn line_timestamp(line_index: usize) -> DateTime<Utc> {
    Utc.timestamp_opt(1_800_000_000 + line_index as i64, 0)
        .unwrap()
}

#[derive(Default)]
struct Sequencer {
    sequences: BTreeMap<StreamId, u64>,
}

impl Sequencer {
    fn event(&mut self, event_id: String, draft: HarnessEventDraftV1) -> HarnessEventV1 {
        let sequence = self.sequences.entry(draft.stream_id.clone()).or_insert(0);
        *sequence += 1;

        HarnessEventV1 {
            event_id: EventId::new(event_id),
            stream_id: draft.stream_id,
            sequence: *sequence,
            correlation: draft.correlation,
            timestamp: draft.timestamp,
            semantics: draft.semantics,
            provider_sequence: draft.provider_sequence,
            payload: draft.payload,
        }
    }
}

fn view(payload: &HarnessEventPayloadV1) -> Option<Value> {
    match payload {
        HarnessEventPayloadV1::BackgroundWork(work) => {
            let mut value = json!({
                "work": work.work_id.as_str(),
                "generation": work.generation,
                "kind": work.kind,
                "status": work.status,
            });
            let optional = [
                ("description", work.description.clone()),
                ("progress", work.progress.clone()),
                (
                    "launch",
                    work.launch_tool_call_id.as_ref().map(ToString::to_string),
                ),
                ("error", work.error.clone()),
            ];

            for (key, field) in optional {
                if let Some(field) = field {
                    value[key] = json!(field);
                }
            }

            Some(value)
        }

        HarnessEventPayloadV1::BackgroundRoster(roster) => Some(json!({
            "roster": roster
                .work
                .iter()
                .map(|entry| json!([entry.work_id.as_str(), entry.kind]))
                .collect::<Vec<_>>(),
        })),

        _ => None,
    }
}

#[test]
fn claude_background_records_match_the_independent_oracle() {
    let expected: Value = serde_json::from_str(EXPECTED).unwrap();
    let mut decoder = decoder("sess-bg", "root");
    let mut observed = Vec::new();

    for (line_index, line) in FIXTURE.lines().enumerate() {
        let drafts = decoder
            .decode_line_at(line, line_timestamp(line_index))
            .unwrap();

        for draft in drafts {
            if let HarnessEventPayloadV1::ToolOutput(output) = &draft.payload {
                assert_eq!(output.status, ToolStatus::Completed);
            }

            observed.extend(view(&draft.payload));
        }
    }

    assert_eq!(Value::Array(observed), expected["events"]);
}

#[test]
fn progress_derives_start_from_provider_elapsed_time_only() {
    let mut decoder = decoder("s", "root");
    decoder
        .decode_line(r#"{"type":"system","subtype":"init","session_id":"s"}"#)
        .unwrap();

    let drafts = decoder
        .decode_line_at(
            r#"{"type":"system","subtype":"task_progress","task_id":"t","description":"d","usage":{"total_tokens":1,"tool_uses":1,"duration_ms":30000}}"#,
            Utc.timestamp_opt(1_800_000_100, 0).unwrap(),
        )
        .unwrap();

    let HarnessEventPayloadV1::BackgroundWork(work) = &drafts[0].payload else {
        panic!("expected background work");
    };

    assert_eq!(
        work.started_at,
        Some(Utc.timestamp_opt(1_800_000_070, 0).unwrap())
    );
    assert_eq!(work.progress, None);
}

/// Writes the input of the GUI bridge test. Set `VERTEBRAE_UPDATE_GOLDEN=1`
/// to rewrite it after an intended change.
#[test]
fn claude_background_stream_matches_the_gui_bridge_golden() {
    let golden_path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../gui/src-tauri/src/local_chat/harnesses/fixtures/background-claude.harness.json");
    let mut decoder = decoder("sess-bg", "local-chat:backend-1");
    let mut sequencer = Sequencer::default();
    let mut events = Vec::new();

    for (line_index, line) in FIXTURE.lines().enumerate() {
        // Turn context as the interactive runtime sets it: lines 1-7 are
        // turn-1 up to its `result`, 8-11 arrive while idle, 12+ are turn-2.
        decoder.context_mut().turn_id = match line_index {
            0..=6 => Some(TurnId::from("turn-1")),
            7..=10 => None,
            _ => Some(TurnId::from("turn-2")),
        };

        let drafts = decoder
            .decode_line_at(line, line_timestamp(line_index))
            .unwrap();

        for draft in drafts {
            let bridged = matches!(
                draft.payload,
                HarnessEventPayloadV1::BackgroundWork(_)
                    | HarnessEventPayloadV1::BackgroundRoster(_)
                    | HarnessEventPayloadV1::TurnFinished(_)
            );

            if bridged {
                let event_id = format!("claude-{}", events.len() + 1);
                events.push(sequencer.event(event_id, draft));
            }
        }
    }

    let actual = serde_json::to_string_pretty(&events).unwrap() + "\n";
    if std::env::var_os("VERTEBRAE_UPDATE_GOLDEN").is_some() {
        std::fs::write(&golden_path, &actual).unwrap();
    }
    let golden = std::fs::read_to_string(&golden_path)
        .unwrap_or_else(|error| panic!("{}: {error}", golden_path.display()));

    assert_eq!(
        actual, golden,
        "regenerate with VERTEBRAE_UPDATE_GOLDEN=1 after review"
    );
}
